INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'gulf-pillars-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Gulf Pillars in Hidd.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من أركان الخليج في Hidd.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grade-A civil and MEP contractor executing industrial warehouses, commercial complexes, and municipal infrastructure across Bahrain. Focusing on Commercial HVAC & MEP Fit-Out, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مقاول درجة أولى للأعمال المدنية والكهروميكانيكية لتنفيذ المستودعات الصناعية والمجمعات التجارية. من خلال خدمة تنفيذ أعمال التكييف والكهروميكانيك نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Grade-A civil and MEP contractor executing industrial warehouses, commercial complexes, and municipal infrastructure across Bahrain.</p><p>Focusing on <strong>Commercial HVAC & MEP Fit-Out</strong>, our Hidd specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مقاول درجة أولى للأعمال المدنية والكهروميكانيكية لتنفيذ المستودعات الصناعية والمجمعات التجارية.</p><p>من خلال خدمة <strong>تنفيذ أعمال التكييف والكهروميكانيك</strong>، يعمل فريقنا في Hidd على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Gulf Pillars', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | أركان الخليج', 'Executive guide by Gulf Pillars covering Commercial HVAC & MEP Fit-Out benchmarks in Bahrain.', 'دليل تنفيذي من أركان الخليج حول معايير تنفيذ أعمال التكييف والكهروميكانيك في البحرين.', 'Sustainability', '{"construction","sustainability","Hidd","2026"}'::text[], 'Hana Yousef', 'draft', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', false, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
